<script setup>defineProps({ risks: Array }); const emit = defineEmits(['select-risk']);</script>
<template><div class="page"><div class="section-header"><div><span class="eyebrow">RISK OPERATIONS</span><h2>风险中心</h2><p>风险事件由确定性规则划分为 P0 紧急、P1 中等和 P2 低风险；高风险动作必须经人工审批。</p></div></div><div class="filter-bar"><span class="filter-active">全部风险 {{ risks.length }}</span><span>P0 紧急</span><span>P1 中等</span><span>P2 低风险</span><span>待确认</span><div class="filter-note">当前结果已按角色与组织策略过滤</div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>风险事件</th><th>级别与状态</th><th>通知策略</th><th>影响范围</th><th>负责人</th><th>创建时间</th><th/></tr></thead><tbody><tr v-for="risk in risks" :key="risk.id"><td><strong>{{ risk.id }}</strong><span class="table-title">{{ risk.title }}</span></td><td><span :class="['risk-badge', risk.severity.toLowerCase()]">{{ risk.severity }} · {{ risk.status }}</span><small class="table-title">{{ risk.severityDefinition?.acknowledgementMinutes || '—' }} 分钟确认</small></td><td>{{ risk.notificationSummary?.channels?.join(' / ') || '按策略编排' }}</td><td>{{ risk.affected.finishedBatches }} 成品批 · {{ risk.affected.orders }} 订单</td><td>{{ risk.owner }}</td><td>{{ risk.createdAt }}</td><td><button class="link-button" @click="emit('select-risk', risk)">查看闭环 →</button></td></tr></tbody></table></div></section></div></template>
